arr = [int(x) for x in input().split()]
seen = set()
added = set()
result = []
for num in arr:
    if num in seen:
        if num not in added:
            result.append(num)
            added.add(num)
    else:
        seen.add(num)
if not result:
    print(-1, end='')
else:
    print(*result, end='')

